-- tabla articulos
CREATE TABLE `articulos` (
  `linea` varchar(10) NOT NULL,
  `rubro` varchar(10) NOT NULL,
  `codigo` varchar(20) NOT NULL,
  `descripcion` varchar(60) NOT NULL,
  `descripcionAdicional` varchar(4096) NOT NULL,
  `cantidadUnidades` decimal(18,4) NOT NULL,
  `medidaUnidad` varchar(40) NOT NULL,
  `proveedor` int NOT NULL,
  `codigoDelProveedor` varchar(50) NOT NULL,
  `codigoBarras` varchar(30) NOT NULL,
  `rubroIngresosBrutos` int NOT NULL,
  `cuentaContable` int NOT NULL,
  `inactivo` int NOT NULL,
  `imagen` varchar(2048) NOT NULL,
  `tablaComisionVentas` varchar(10) NOT NULL,
  `tablaComisionCobros` varchar(10) NOT NULL,
  `alicuotaIva` int NOT NULL,
  `tipoImpuestoInterno` int NOT NULL,
  `impuestoInterno` decimal(18,4) NOT NULL,
  `costoFecha` date NOT NULL,
  `costoOrigen` int NOT NULL,
  `costoProveedor` int NOT NULL,
  `costoBase` decimal(18,4) NOT NULL,
  `costoRecDto1` decimal(8,2) NOT NULL,
  `costoRecDto2` decimal(8,2) NOT NULL,
  `costoRecDto3` decimal(8,2) NOT NULL,
  `costoRecDto4` decimal(8,2) NOT NULL,
  `costoRecDto5` decimal(8,2) NOT NULL,
  `costoMoneda` varchar(3) NOT NULL,
  `costo` decimal(18,4) NOT NULL,
  `stockMinimo` decimal(18,4) NOT NULL,
  `puntoPedido` decimal(18,4) NOT NULL,
  `stockMaximo` decimal(18,4) NOT NULL,
  `modoStock` int NOT NULL,
  `modoLinea` varchar(10) NOT NULL,
  `modoRubro` varchar(10) NOT NULL,
  `modoArticulo` varchar(20) NOT NULL,
  `stockEnLinea` varchar(10) NOT NULL,
  `stockEnRubro` varchar(10) NOT NULL,
  `stockEnArticulo` varchar(20) NOT NULL,
  `datoVariable1` int NOT NULL,
  `datoVariable2` int NOT NULL,
  `datoVariable3` int NOT NULL,
  `datoVariable4` varchar(50) NOT NULL,
  `datoVariable5` varchar(50) NOT NULL,
  `datoVariable6` varchar(50) NOT NULL,
  `datoVariable7` varchar(50) NOT NULL,
  `datoVariable8` varchar(50) NOT NULL,
  `datoVariable9` varchar(50) NOT NULL,
  `datoVariable10` varchar(50) NOT NULL,
  `datoVariable11` varchar(50) NOT NULL,
  `datoVariable12` varchar(50) NOT NULL,
  `datoVariable13` varchar(50) NOT NULL,
  `datoVariable14` varchar(50) NOT NULL,
  `datoVariable15` varchar(50) NOT NULL,
  `avisoEntradaMercaderias` varchar(50) NOT NULL,
  `avisoCompras` varchar(50) NOT NULL,
  `avisoComprobantes` varchar(50) NOT NULL,
  `avisoPedidos` varchar(50) NOT NULL,
  `avisoVentas` varchar(50) NOT NULL,
  `anotaciones` varchar(2000) NOT NULL,
  `mostrar_en_testbd` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`linea`,`rubro`,`codigo`),
  KEY `articulos_codigo` (`codigo`),
  KEY `articulos_descripcion` (`descripcion`),
  KEY `articulos_codigo_proveedor_codigoDelProveedor` (`proveedor`,`codigoDelProveedor`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

